"use client";

import { geoMercator, geoPath, type GeoPermissibleObjects } from "d3-geo";
import { useEffect, useRef } from "react";
import { cancelFrame, frame, type MotionValue } from "motion/react";
import mapAssets from "../public/portfolio/assets.json";
import { getCameraPose, getChapter } from "../lib/book-camera";
import styles from "./book-journey.module.css";
import { useLanguage } from "./language-provider";
import { mapNames } from "../content/translations";

// Mainland-only, simplified outline generated by scripts/prepare-outline.mjs.
const OUTLINE_URL = "/portfolio/vietnam-outline.geojson";
const ROUTE_INTRO_DELAY = 350;
const ROUTE_INTRO_DURATION = 2200;
const ARRIVAL_PULSE = 900;

let cachedMainlandPath: Path2D | undefined;
let mainlandRequest: Promise<Path2D | undefined> | undefined;
// The route intro plays once per page view, even if the effect re-runs on a
// language switch or when the journey upgrades from its static presentation.
let routeIntroStart: number | undefined;

type Box = { x: number; y: number; width: number; height: number };

function loadMainlandPath(baseProjection: ReturnType<typeof geoMercator>) {
  mainlandRequest ??= fetch(OUTLINE_URL)
    .then((response) => (response.ok ? response.json() : undefined))
    .then((data) => {
      const geometry = data?.geometry as GeoPermissibleObjects | undefined;
      if (geometry) {
        const outline = geoPath(baseProjection).digits(6)(geometry);
        if (outline) cachedMainlandPath = new Path2D(outline);
      }
      return cachedMainlandPath;
    })
    .catch(() => {
      mainlandRequest = undefined;
      return undefined;
    });
  return mainlandRequest;
}

const clamp = (value: number) => Math.max(0, Math.min(1, value));
const easeInOut = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
const overlaps = (a: Box, b: Box) =>
  a.x < b.x + b.width &&
  a.x + a.width > b.x &&
  a.y < b.y + b.height &&
  a.y + a.height > b.y;

export function MapLinework({
  progress,
  staticMode,
}: {
  progress: MotionValue<number>;
  staticMode: boolean;
}) {
  const { language } = useLanguage();
  const canvas = useRef<HTMLCanvasElement>(null);
  const routeCanvas = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const element = canvas.current;
    const routeElement = routeCanvas.current;
    if (!element || !routeElement) return;
    const context = element.getContext("2d");
    const routeContext = routeElement.getContext("2d");
    if (!context || !routeContext) return;
    let scheduled = false;
    let disposed = false;
    let width = 0;
    let height = 0;
    let dpr = 1;
    let mobile = false;
    let compassBox: Box = { x: 0, y: 0, width: 0, height: 0 };
    let gutterBand: Box = { x: 0, y: 0, width: 0, height: 0 };
    let signatureBox: Box = { x: 0, y: 0, width: 0, height: 0 };
    let destinationSize = { width: 80, height: 29 };
    let mainlandPath = cachedMainlandPath;
    // Labels use the site's self-hosted faces, which carry full Vietnamese coverage.
    const style = getComputedStyle(element);
    const sans =
      style.getPropertyValue("--font-geist-sans").trim() || "Arial, sans-serif";
    const serif =
      style.getPropertyValue("--font-book").trim() || "Georgia, serif";
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    ).matches;
    const animateIntro = !staticMode && !reducedMotion;
    if (animateIntro)
      routeIntroStart ??= performance.now() + ROUTE_INTRO_DELAY;
    const baseScale = mapAssets.maps[0]!.projection.scale;
    const origin: [number, number] = [
      mapAssets.geographicAnchor.longitude,
      mapAssets.geographicAnchor.latitude,
    ];
    // Retain geographic paths in one Mercator coordinate space. Only the camera
    // matrix changes during a zoom; never stream thousands of rings per frame.
    const baseProjection = geoMercator()
      .center(origin)
      .scale(baseScale)
      .translate([0, 0]);
    const projection = geoMercator().center(origin);
    const routePoints = mapAssets.journeyRoute.coordinates.map(
      (point) => baseProjection(point as [number, number])!,
    );
    const routeLengths = [0];
    for (let i = 1; i < routePoints.length; i++) {
      const [x0, y0] = routePoints[i - 1]!;
      const [x1, y1] = routePoints[i]!;
      routeLengths.push(routeLengths[i - 1]! + Math.hypot(x1 - x0, y1 - y0));
    }
    const routeLength = routeLengths.at(-1)!;
    const routePath = new Path2D();
    routePoints.forEach(([x, y], index) => {
      if (index === 0) routePath.moveTo(x, y);
      else routePath.lineTo(x, y);
    });
    // Partial route for the intro, ending exactly at the given fraction of its length.
    const partialRoute = (fraction: number) => {
      const target = fraction * routeLength;
      const path = new Path2D();
      path.moveTo(...routePoints[0]!);
      let head = routePoints[0]!;
      for (let i = 1; i < routePoints.length; i++) {
        const start = routeLengths[i - 1]!;
        const end = routeLengths[i]!;
        const [x0, y0] = routePoints[i - 1]!;
        const [x1, y1] = routePoints[i]!;
        if (end <= target) {
          path.lineTo(x1, y1);
          head = routePoints[i]!;
          continue;
        }
        const t = (target - start) / (end - start || 1);
        head = [x0 + (x1 - x0) * t, y0 + (y1 - y0) * t];
        path.lineTo(...head);
        break;
      }
      return { path, head };
    };
    const setData = (key: string, value: string) => {
      if (element.dataset[key] !== value) element.dataset[key] = value;
    };
    const camera = () => {
      const p = staticMode ? 0 : progress.get();
      const pose = getCameraPose(p, mapAssets.maps);
      projection
        .scale((pose.scale * width) / 2048)
        .translate([pose.anchor.x * width, pose.anchor.y * height]);
      const fadeAmount = Math.max(0, Math.min(1, (0.58 - p) / 0.15));
      return {
        p,
        pose,
        fade: fadeAmount * fadeAmount * (3 - 2 * fadeAmount),
        zoom: projection.scale() / baseScale,
        pinX: pose.anchor.x * width,
        pinY: pose.anchor.y * height,
      };
    };
    // The route lives on its own canvas beneath the labels, so the intro redraws
    // only this short path instead of the outline, clip and label layout.
    const drawRoute = () => {
      if (disposed || !width || !height) return;
      routeContext.setTransform(dpr, 0, 0, dpr, 0, 0);
      routeContext.clearRect(0, 0, width, height);
      const { fade, zoom, pinX, pinY } = camera();
      const introElapsed =
        animateIntro && routeIntroStart !== undefined
          ? performance.now() - routeIntroStart
          : Infinity;
      const reveal = easeInOut(clamp(introElapsed / ROUTE_INTRO_DURATION));
      const lineWidth = width < 500 ? 1 : 1.25;
      if (fade > 0 && reveal > 0) {
        routeContext.save();
        routeContext.translate(pinX, pinY);
        routeContext.scale(zoom, zoom);
        routeContext.lineCap = "round";
        routeContext.lineJoin = "round";
        // The itinerary is validated against the mainland at build time; once it
        // is fully drawn, clip it to the outline as the camera zooms in.
        if (reveal >= 1 && mainlandPath) routeContext.clip(mainlandPath);
        const route = reveal >= 1 ? { path: routePath, head: null } : partialRoute(reveal);
        routeContext.lineWidth = (lineWidth + 2) / zoom;
        routeContext.strokeStyle = `rgba(255, 250, 234, ${fade * 0.8})`;
        routeContext.stroke(route.path);
        routeContext.lineWidth = lineWidth / zoom;
        routeContext.setLineDash([4 / zoom, 4 / zoom]);
        routeContext.strokeStyle = `rgba(170, 62, 52, ${fade * 0.95})`;
        routeContext.stroke(route.path);
        routeContext.setLineDash([]);
        if (route.head) {
          // A small traveller leads the line from Hanoi towards Da Lat.
          routeContext.beginPath();
          routeContext.arc(route.head[0], route.head[1], 3.2 / zoom, 0, Math.PI * 2);
          routeContext.fillStyle = `rgba(170, 62, 52, ${fade})`;
          routeContext.fill();
          routeContext.lineWidth = 1.4 / zoom;
          routeContext.strokeStyle = `rgba(255, 251, 237, ${fade})`;
          routeContext.stroke();
        }
        routeContext.restore();
      }
      const arrival = introElapsed - ROUTE_INTRO_DURATION;
      if (arrival > 0 && arrival < ARRIVAL_PULSE) {
        // One soft ring when the line reaches Da Lat.
        const t = arrival / ARRIVAL_PULSE;
        routeContext.beginPath();
        routeContext.arc(
          pinX,
          pinY,
          (mobile ? 6 : 8) + t * (mobile ? 16 : 24),
          0,
          Math.PI * 2,
        );
        routeContext.lineWidth = 2;
        routeContext.strokeStyle = `rgba(172, 64, 55, ${0.55 * (1 - t)})`;
        routeContext.stroke();
      }
      setData("routeWidth", String(lineWidth));
      // Keep the intro running on Motion's next render frame.
      if (introElapsed < ROUTE_INTRO_DURATION + ARRIVAL_PULSE)
        frame.render(drawRoute, false, false);
    };
    const draw = () => {
      scheduled = false;
      if (disposed || !width || !height) return;
      context.setTransform(dpr, 0, 0, dpr, 0, 0);
      context.clearRect(0, 0, width, height);
      const { p, pose, fade, zoom, pinX, pinY } = camera();
      if (fade > 0 && mainlandPath) {
        context.save();
        context.translate(pinX, pinY);
        context.scale(zoom, zoom);
        context.lineCap = "round";
        context.lineJoin = "round";
        context.lineWidth = 2.6 / zoom;
        context.strokeStyle = `rgba(250, 249, 234, ${0.7 * fade})`;
        context.stroke(mainlandPath);
        context.lineWidth = 0.85 / zoom;
        context.strokeStyle = `rgba(58, 91, 77, ${0.75 * fade})`;
        context.stroke(mainlandPath);
        context.restore();
      }
      // The narrowest phones keep 8px labels so every national name still fits.
      const fontSize = width < 340 ? 8 : width < 500 ? 9 : 11;
      const labelFont = `500 ${fontSize}px ${sans}`;
      const waterFont = `italic ${fontSize + 1}px ${serif}`;
      context.lineJoin = "round";
      const bounds: Box[] = [];
      const earlyChapter = getChapter(p) < 2;
      bounds.push({
        x:
          pinX +
          (earlyChapter
            ? mobile
              ? 15
              : 30
            : -(mobile ? 10 : 14) - destinationSize.width) -
          5,
        y: pinY + (earlyChapter ? (mobile ? -25 : -34) : mobile ? 8 : 9) - 5,
        width: destinationSize.width + 10,
        height: destinationSize.height + 10,
      });
      const pinRadius = mobile ? 11 : 15;
      bounds.push({
        x: pinX - pinRadius,
        y: pinY - pinRadius,
        width: pinRadius * 2,
        height: pinRadius * 2,
      });
      bounds.push(compassBox, gutterBand);
      if (signatureBox.width) bounds.push(signatureBox);
      bounds.push({
        x: width * 0.75,
        y: height * 0.925 - (width < 500 ? 13 : 19),
        width: width * 0.19,
        height: width < 500 ? 18 : 24,
      });
      const labels =
        (
          mapAssets as typeof mapAssets & {
            labels?: {
              name: string;
              longitude: number;
              latitude: number;
              kind: string;
            }[];
          }
        ).labels ?? [];
      const drawnLabels: string[] = [];
      const labelBoxes: (Box & { name: string })[] = [];
      const gutterCenter = gutterBand.x + gutterBand.width / 2;
      for (const label of labels) {
        const labelText =
          language === "en" ? (mapNames[label.name] ?? label.name) : label.name;
        const alpha =
          label.kind === "national"
            ? Math.max(0, Math.min(1, (0.34 - p) / 0.12))
            : label.kind === "regional"
              ? Math.max(0, Math.min(1, (p - 0.18) / 0.1, (0.64 - p) / 0.1))
              : label.kind === "highlands"
                ? Math.max(0, Math.min(1, (p - 0.48) / 0.12, (0.86 - p) / 0.12))
                : Math.max(0, Math.min(1, (p - 0.78) / 0.14));
        if (alpha <= 0) continue;
        const point = projection([label.longitude, label.latitude]);
        if (!point) continue;
        const isWater =
          label.name === "Biển Đông" || label.name.startsWith("Hồ ");
        const isCountry = ["Lào", "Campuchia", "Lâm Đồng"].includes(label.name);
        const isIsland = label.name === "Phú Quốc";
        const isCity =
          !isCountry && !isWater && !isIsland && !label.name.startsWith("QĐ.");
        context.font = isWater ? waterFont : labelFont;
        // On the narrowest atlas, Ho Chi Minh City sits above its point and leaves
        // the space beside the fold for Phu Quoc.
        const belowAnchor =
          width >= 300 && width < 500 && label.name === "TP. Hồ Chí Minh";
        const defaultX =
            isIsland && width < 500
              ? Math.max(point[0] - 27, width * 0.4 + 3)
              : point[0] + 7,
          defaultY = point[1] + (isIsland ? 5 : belowAnchor ? 4 : -7);
        const textWidth = context.measureText(labelText).width;
        const candidates: [number, number][] = [
          [defaultX, defaultY],
          [point[0] - textWidth - 7, defaultY],
        ];
        // Near the book's fold, slide the label just clear of the gutter, as long as
        // it stays within reach of its point instead of landing on the far page.
        if (gutterBand.width && Math.abs(point[0] - gutterCenter) < textWidth + 24)
          for (const x of [
            gutterBand.x + gutterBand.width + 4,
            gutterBand.x - textWidth - 4,
          ])
            if (Math.max(0, x - point[0], point[0] - (x + textWidth)) <= 48)
              candidates.push([x, defaultY]);
        candidates.push(
          [defaultX, point[1] + fontSize + 10],
          [point[0] - textWidth - 7, point[1] + fontSize + 10],
          [point[0] - textWidth / 2, point[1] - 18],
          [point[0] - textWidth / 2, point[1] + fontSize + 10],
          [point[0] - textWidth / 2, point[1] + fontSize + 18],
        );
        // On desktop the left page holds the chapter text; on phones the atlas
        // spans both pages, so only the outer margin is off limits.
        const minX = mobile ? 6 : width * (isIsland ? 0.4 : 0.43);
        const placement = candidates
          .map(([x, y]) => ({
            x,
            y,
            box: {
              x: x - 3,
              y: y - fontSize - 3,
              width: textWidth + 6,
              height: fontSize + 7,
            },
          }))
          .find(
            ({ box }) =>
              box.x >= minX &&
              box.x + box.width <= width - (mobile ? 6 : 15) &&
              box.y >= (width < 500 ? 12 : 30) &&
              box.y + box.height <=
                height - (width < 500 || isIsland ? 12 : 28) &&
              !bounds.some((b) => overlaps(box, b)),
          );
        if (!placement) continue;
        const { x, y, box } = placement;
        bounds.push(box);
        labelBoxes.push({ name: labelText, ...box });
        context.globalAlpha = alpha;
        context.fillStyle = isWater
          ? "#416f78"
          : isCountry
            ? "#727a66"
            : "#354e42";
        if (isCity) {
          context.beginPath();
          context.arc(
            point[0],
            point[1],
            label.name === "Hà Nội" ? 2.4 : 1.8,
            0,
            Math.PI * 2,
          );
          // Hanoi keeps the route's red for both its dot and its name.
          context.fillStyle = label.name === "Hà Nội" ? "#aa3e34" : "#354e42";
          context.fill();
          context.lineWidth = 1.3;
          context.strokeStyle = "#fffbed";
          context.stroke();
        }
        context.lineWidth = 3;
        context.strokeStyle = "rgba(250, 248, 231, 0.9)";
        context.strokeText(labelText, x, y);
        context.fillText(labelText, x, y);
        drawnLabels.push(labelText);
      }
      context.globalAlpha = 1;
      // Mercator scale varies with latitude; keep the ruler physically meaningful while zooming.
      const rulerY = height * 0.925;
      const rulerLatitude =
        projection.invert?.([width * 0.88, rulerY])?.[1] ??
        mapAssets.geographicAnchor.latitude;
      const metersPerPixel =
        (6371008.8 * Math.cos((rulerLatitude * Math.PI) / 180)) /
        projection.scale();
      const targetDistance = metersPerPixel * (width < 500 ? 38 : 66);
      const magnitude = 10 ** Math.floor(Math.log10(targetDistance));
      const distance =
        [1, 2, 5, 10]
          .map((step) => step * magnitude)
          .find((step) => step >= targetDistance) ?? magnitude * 10;
      const rulerWidth = distance / metersPerPixel;
      const rulerX = width * 0.92 - rulerWidth;
      const rulerText =
        distance >= 1000 ? `${distance / 1000} km` : `${distance} m`;
      context.font = `500 ${width < 500 ? 8 : 9}px ${sans}`;
      context.textAlign = "center";
      context.lineWidth = 3;
      context.strokeStyle = "#f8f5e9";
      context.strokeText(rulerText, rulerX + rulerWidth / 2, rulerY - 7);
      context.fillStyle = "#496154";
      context.fillText(rulerText, rulerX + rulerWidth / 2, rulerY - 7);
      context.beginPath();
      context.moveTo(rulerX, rulerY - 3);
      context.lineTo(rulerX, rulerY);
      context.lineTo(rulerX + rulerWidth, rulerY);
      context.lineTo(rulerX + rulerWidth, rulerY - 3);
      context.lineWidth = 2.6;
      context.strokeStyle = "#f8f5e9";
      context.stroke();
      context.lineWidth = 0.8;
      context.strokeStyle = "#496154";
      context.stroke();
      context.textAlign = "start";
      // Test hooks: written only when they change, not on every frame.
      setData("scaleMeters", String(distance));
      setData("scalePixels", String(rulerWidth));
      setData("metersPerPixel", String(metersPerPixel));
      setData("atlas", "true");
      setData("labelSize", String(fontSize));
      setData("labels", JSON.stringify(drawnLabels));
      setData("labelBoxes", JSON.stringify(labelBoxes));
      setData("cameraScale", String(pose.scale));
      setData("rendered", "true");
      drawRoute();
    };
    const schedule = () => {
      if (disposed || scheduled) return;
      scheduled = true;
      // Share Motion's render phase with GeographicPlate transforms. A separate
      // requestAnimationFrame would leave linework one frame behind the artwork.
      frame.render(draw, false, true);
    };
    const measure = () => {
      width = element.clientWidth;
      height = element.clientHeight;
      mobile = window.matchMedia("(max-width: 640px)").matches;
      const paper = element.closest("[data-book-paper]");
      const compass = paper?.querySelector<HTMLElement>("[data-compass]");
      const destination = paper?.querySelector<HTMLElement>("[data-map-label]");
      const gutter = paper?.querySelector<HTMLElement>("[data-gutter]");
      const signature = paper?.querySelector<HTMLElement>("[data-signature]");
      if (compass)
        compassBox = {
          x: compass.offsetLeft - 6,
          y: compass.offsetTop - 6,
          width: compass.offsetWidth + 12,
          height: compass.offsetHeight + 12,
        };
      if (gutter) {
        // The gutter is centred with translateX(-50%); keep labels off its dark fold.
        const left = gutter.offsetLeft - gutter.offsetWidth / 2;
        gutterBand = {
          x: left + gutter.offsetWidth * 0.28,
          y: 0,
          width: gutter.offsetWidth * 0.4,
          height,
        };
      }
      signatureBox =
        mobile && signature && signature.offsetWidth
          ? {
              x: signature.offsetLeft - 4,
              y: signature.offsetTop - 6,
              width: signature.offsetWidth + 8,
              height: signature.offsetHeight + 12,
            }
          : { x: 0, y: 0, width: 0, height: 0 };
      if (destination)
        destinationSize = {
          width: destination.offsetWidth,
          height: destination.offsetHeight,
        };
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      const pixelWidth = Math.round(width * dpr);
      const pixelHeight = Math.round(height * dpr);
      for (const target of [element, routeElement]) {
        if (target.width !== pixelWidth || target.height !== pixelHeight) {
          target.width = pixelWidth;
          target.height = pixelHeight;
        }
      }
      schedule();
    };
    const unsubscribe = progress.on("change", schedule);
    const observer = new ResizeObserver(() => frame.read(measure));
    observer.observe(element);
    const paper = element.closest("[data-book-paper]");
    paper
      ?.querySelectorAll("[data-map-label], [data-compass]")
      .forEach((node) => observer.observe(node));
    void loadMainlandPath(baseProjection).then((path) => {
      if (!disposed) {
        mainlandPath = path;
        schedule();
      }
    });
    // Redraw once the self-hosted faces are ready; until then the fallbacks render.
    void Promise.all([
      document.fonts.load(`500 11px ${sans}`),
      document.fonts.load(`italic 12px ${serif}`),
    ]).then(
      () => schedule(),
      () => undefined,
    );
    document.fonts.addEventListener("loadingdone", schedule);
    frame.read(measure);
    return () => {
      disposed = true;
      unsubscribe();
      observer.disconnect();
      document.fonts.removeEventListener("loadingdone", schedule);
      cancelFrame(draw);
      cancelFrame(drawRoute);
      cancelFrame(measure);
    };
  }, [progress, staticMode, language]);
  return (
    <>
      <canvas
        ref={routeCanvas}
        className={styles.mapLinework}
        aria-hidden="true"
        data-map-route
      />
      <canvas
        ref={canvas}
        className={styles.mapLinework}
        aria-hidden="true"
        data-map-linework
      />
    </>
  );
}
